        .hero p { font-size: 18px; margin-bottom: 30px; max-width: 600px; margin-left: auto; margin-right: auto; }

        /* Features */
        .features-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); gap: 30px; margin-top: -50px; position: relative; z-index: 10; }
        .feature-card { background: var(--white); padding: 30px; border-radius: 8px; box-shadow: var(--shadow); text-align: center; }
        .feature-icon { width: 60px; height: 60px; background: #E0F2F1; color: var(--primary-color); border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 20px; font-size: 24px; font-weight: bold; }
        .feature-card h3 { margin-bottom: 10px; }
        .feature-card p { color: var(--text-light); font-size: 14px; }

