        .cta-section { background: var(--white); padding: 80px 0; }
        .cta-box { background: #263238; color: var(--white); padding: 60px; border-radius: 12px; display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; }
        .cta-text h2 { margin-bottom: 15px; }
        .cta-text p { color: #B0BEC5; margin-bottom: 25px; }
