                </ul>
            </nav>
            <a href="booking.html" class="btn-primary">立即预约</a>
        </div>
    </header>

    <div class="section">
        <div class="container">
            <div class="form-wrapper">
                <div class="form-header">
                    <h2>在线预约保洁服务</h2>
                    <p>请填写以下信息，我们将尽快与您联系确认上门时间。</p>
                </div>

                <form id="bookingForm" onsubmit="handleBooking(event)">
                    <div class="form-group">
                        <label>预约类型 <span style="color:red">*</span></label>
                        <div class="radio-group">
                            <label class="radio-option">
                                <input type="radio" name="serviceType" value="regular" checked> 日常保洁
                            </label>
                            <label class="radio-option">
                                <input type="radio" name="serviceType" value="deep"> 深度保洁
                            </label>
                            <label class="radio-option">
                                <input type="radio" name="serviceType" value="renovation"> 开荒保洁
                            </label>
                        </div>
                    </div>

                    <div class="form-group">
                        <label for="name">您的称呼 <span style="color:red">*</span></label>
                        <input type="text" id="name" class="form-control" placeholder="例如：王先生/李女士" required>
                    </div>

                    <div class="form-group">
                        <label for="phone">联系电话 <span style="color:red">*</span></label>
                        <input type="tel" id="phone" class="form-control" placeholder="请输入您的手机号码" required>
                    </div>

                    <div class="form-group">
                        <label for="address">服务地址 <span style="color:red">*</span></label>
                        <input type="text" id="address" class="form-control" placeholder="北京市朝阳区/海淀区/通州区..." required>
                    </div>

                    <div class="form-group">
                        <label for="date">期望上门日期 <span style="color:red">*</span></label>
                        <input type="date" id="date" class="form-control" required>
                    </div>

                    <div class="form-group">
                        <label for="notes">特殊备注</label>
                        <input type="text" id="notes" class="form-control" placeholder="例如：家里有宠物，需要带鞋套等">
                    </div>

                    <button type="submit" class="btn-submit">提交预约申请</button>

                    <div id="successMessage" class="success-message">
                        <h3>预约提交成功！</h3>
                        <p>我们的客服将在 30 分钟内致电您确认具体上门时间。</p>
                        <p style="margin-top: 10px; font-size: 14px;">您也可以拨打 400-123-4567 直接联系人工服务。</p>
                        <button type="button" class="btn-primary" onclick="location.reload()" style="margin-top: 15px;">返回首页</button>
                    </div>
                </form>
            </div>
        </div>
    </div>

    <footer>
        <div class="container">
            <p>&copy; 2023 洁家家政服务有限公司 版权所有</p>
        </div>
    </footer>

    <script>
        function handleBooking(e) {
            e.preventDefault();
            // 简单的表单验证模拟
            const name = document.getElementById('name').value;
            const phone = document.getElementById('phone').value;

            if(name.length < 2 || phone.length < 11) {
                alert('请填写正确的姓名和手机号');
                return;
            }

            // 模拟提交过程
            const btn = document.querySelector('.btn-submit');
            btn.textContent = '提交中...';
            btn.disabled = true;

            setTimeout(function() {
                document.getElementById('bookingForm').style.display = 'none';
                document.getElementById('successMessage').style.display = 'block';
            }, 1500);
        }

        // 设置日期选择器最小日期为今天
        const dateInput = document.getElementById('date');
        dateInput.min = new Date().toISOString().split("T")[0];
    </script>
